a<-file.path(OUT,'00_input_audit');man<-fread(file.path(PREV,'00_audit/manifest.csv'));stopifnot(nrow(man)==59,uniqueN(man$patient_id)==42);writecsv(man,file.path(a,'manifest.csv'))
