# Grouping rules never split equal scores by random assignment.
globalmed<-median(m[clinical_group!='Normal',LLPS77_AUC]);st<-rbindlist(lapply(split(m,m$specimen_id),function(z){s<-z$LLPS77_AUC;med<-median(s);q<-quantile(s,c(.3,.7),type=7);rbindlist(lapply(c('within_median','exclude_median_ties','top_bottom30','global_tumor_median'),function(method){g<-switch(method,within_median=ifelse(s>med,'high','low'),exclude_median_ties=ifelse(s>med,'high',ifelse(s<med,'low',NA)),top_bottom30=ifelse(s>q[2],'high',ifelse(s<q[1],'low',NA)),global_tumor_median=ifelse(z$clinical_group=='Normal',NA,ifelse(s>globalmed,'high','low')));data.table(cell=z$cell,specimen_id=z$specimen_id,patient_id=z$patient_id,dataset=z$dataset,clinical_group=z$clinical_group,score=s,method=method,state=g,median=med,q30=q[1],q70=q[2],global_median=globalmed)}))}));writecsv(st,file.path(OUT,'01_LLPS_stratification/cell_assignments.csv.gz'))
ss<-st[,.(C5_cells=.N,high=sum(state=='high',na.rm=TRUE),low=sum(state=='low',na.rm=TRUE),excluded=sum(is.na(state)),median_ties=sum(score==median),zero_fraction=mean(score==0),high_mean=mean(score[state=='high'&!is.na(state)]),low_mean=mean(score[state=='low'&!is.na(state)])),by=.(method,specimen_id,patient_id,dataset,clinical_group)];ss[,score_difference:=high_mean-low_mean];writecsv(ss,file.path(OUT,'01_LLPS_stratification/specimen_group_counts.csv'))
el<-ss[rep(seq_len(.N),each=4)];el[,min_cells:=rep(c(5,10,20,30),nrow(ss))];el[,eligible:=high>min_cells&low>min_cells];writecsv(el,file.path(OUT,'01_LLPS_stratification/specimen_eligibility.csv'));summ<-el[,.(specimens=sum(eligible),patients=uniqueN(patient_id[eligible])),by=.(method,min_cells,clinical_group)];writecsv(summ,file.path(OUT,'01_LLPS_stratification/feasibility_summary.csv'));print(summ)
